model.Destinations.push( {"Categories":[10],"HiddenTopics":[24],"Topics":[20],"Id":29,"TextResource":{"Name":"cava-del-vino","Translations":[{"Text":"Cava del Vino","Abbreviation":""},{"Text":"Cava del Vino","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"3","Id":123}]},"Description":{"Name":"description","Translations":[{"Text":"<p>Las botellas de las más destacadas viñas del territorio nacional reunidas en una tienda especializada que lo llevará en un viaje por las tradicionales cavas de los valles de Chile, viviendo todo el proceso que confluye hasta la creación de algunos de los mejores vinos del mundo.<\/p>\n","Abbreviation":""},{"Text":"<p>Wine bottles from the most outstanding Chilean wineries gathered together in a specialized shop that will take you on a tour of the traditional Chilean valley wine cellars, to live through the process that ends up with the creation of some of the best wines in the world.<\/p>\n","Abbreviation":""}]},"Created":"1488916772","Updated":"1488916772","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/029_cava-del-vino.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/wines\/cava-del-vino","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/vinos\/cava-del-vino","Abbreviation":""}}},"ExternalDatas":{"Data":[{"key":"field_phone","label":"Phone","field_name":"field_shop_phone"},{"key":"field_shop_site_internet","label":"Website","field_name":"field_shop_site_internet"},{"key":"field_opening_hours","label":"Opening hours","field_name":"field_shop_openinghours"}]},"HasAdditionalInfo":true});

