model.Destinations.push( {"Categories":[9],"HiddenTopics":[24],"Topics":[6],"Id":41,"TextResource":{"Name":"delta-sky-club","Translations":[{"Text":"Delta Sky Club","Abbreviation":""},{"Text":"Delta Sky Club","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"3","Id":85}]},"Description":{"Name":"description","Translations":[{"Text":"<p>La tradición y experiencia de una de las alianzas aéreas de mayor renombre confluyen en este Salón VIP que le entrega un espacio donde poder disfrutar de manera amena la previa de su vuelo, ofreciendo servicios que harán de la espera un momento reconfortante.<\/p>\n","Abbreviation":""},{"Text":"<p>The tradition and experience of one of the best known airline alliances merge in this VIP Lounge, which provides a setting where you can spend pleasant and comforting moments while you wait for your flight to depart.<\/p>\n","Abbreviation":""}]},"Created":"1488916780","Updated":"1488916780","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/041_delta-sky-club.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/vip-rooms\/delta-sky-club","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/salones-vip-privados\/delta-sky-club","Abbreviation":""}}},"LogoMap":{"Translations":{"1":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/041_delta-sky-club.png","LocalUrl":"Destinations\/41\/MapLogo_1.png"},"0":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/041_delta-sky-club.png","LocalUrl":"Destinations\/41\/MapLogo_0.png"}}},"ExternalDatas":{"Data":[]},"HasAdditionalInfo":false});

