model.Destinations.push( {"Categories":[8],"HiddenTopics":[24],"Topics":[3],"Id":97,"TextResource":{"Name":"pronto-copec","Translations":[{"Text":"Pronto Copec","Abbreviation":""},{"Text":"Pronto Copec","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"3","Id":116}]},"Description":{"Name":"description","Translations":[{"Text":"<p>Pronto Copec, lo mejor de las carreteras de Chile ahora en el Aeropuerto. Especializado en sandwich, hamburguesas y el tradicional completo. No dejes de probar las ensaladas frescas y la variada oferta de bebidas, jugos, café y tortas.<\/p>\n","Abbreviation":""},{"Text":"<p>We offer the best hamburgers, sandwhiches and hot dogs. Are you on a diet ? Try our daily fresh salads, fruit juices, coffee and our variety of desserts. On the go? We also do take out ! We are located at the round point on the 3rd floor. We are open 24\\\/7. Come visit us!<\/p>\n","Abbreviation":""}]},"Created":"1488916788","Updated":"1488916788","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/097_pronto-copec.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/fast-food\/pronto-copec","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/comida-rapida\/pronto-copec","Abbreviation":""}}},"LogoMap":{"Translations":{"1":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/097_pronto-copec.png","LocalUrl":"Destinations\/97\/MapLogo_1.png"},"0":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/097_pronto-copec.png","LocalUrl":"Destinations\/97\/MapLogo_0.png"}}},"ExternalDatas":{"Data":[]},"HasAdditionalInfo":false});

