model.Destinations.push( {"Categories":[10],"HiddenTopics":[10,24],"Topics":[12],"Id":102,"TextResource":{"Name":"rumbo-sur-chile","Translations":[{"Text":"Rumbo Sur Chile","Abbreviation":""},{"Text":"Rumbo Sur Chile","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"3","Id":158}]},"Description":{"Name":"description","Translations":[{"Text":"<p>La historia y esencia de nuestro país en una tienda de souvenirs imperdible para turistas y personas que viajen al extranjero, al entregar recuerdos creados con materias primas nacionales que evocan cada paisaje de Chile.<\/p>\n","Abbreviation":""},{"Text":"<p>The history and essence of Chile in a must-visit souvenir shop both for tourists and locals traveling abroad, with souvenirs made with local raw materials reminiscent of the country's typical landscapes.<\/p>\n","Abbreviation":""}]},"Created":"1488916788","Updated":"1488916788","Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/arthesany-souvenirs\/rumbo-sur-chile","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/artesanias-y-souvenirs\/rumbo-sur-chile","Abbreviation":""}}},"LogoMap":{"Translations":{"1":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/102_rumbo-sur-chile.png","LocalUrl":"Destinations\/102\/MapLogo_1.png"},"0":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/102_rumbo-sur-chile.png","LocalUrl":"Destinations\/102\/MapLogo_0.png"}}},"ExternalDatas":{"Data":[{"key":"field_phone","label":"Phone","field_name":"field_shop_phone"},{"key":"field_shop_site_internet","label":"Website","field_name":"field_shop_site_internet"},{"key":"field_opening_hours","label":"Opening hours","field_name":"field_shop_openinghours"}]},"HasAdditionalInfo":true});

