model.Destinations.push( {"Categories":[1,9],"HiddenTopics":[],"Topics":[6],"Id":104,"TextResource":{"Name":"salon-vip-salon-lounge-pacific-club","Translations":[{"Text":"Salón VIP \"Salón the Lounge Pacific Club\"","Abbreviation":""},{"Text":"Salón VIP \"Salón the Lounge Pacific Club\"","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"2","Id":184},{"FloorId":"2","Id":187}]},"Description":{"Name":"description","Translations":[{"Text":"<p>Un nuevo concepto en salones VIP, ideado para estadías cortas o de mediano plazo, donde podrá encontrar todos los servicios que necesita antes de tu vuelo, con el respaldo y confianza que le brindan los Salones VIP Pacific Club.<\/p>\n","Abbreviation":""},{"Text":"<p>A new concept in VIP lounges designed for short or medium-term stays, where you may find all the services you require before you fly, all with the support and reliability that VIP Pacific Club Lounges give you.<\/p>\n","Abbreviation":""}]},"Created":"1488916788","Updated":"1488916788","Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/vip-rooms\/sal%C3%B3n-vip-sal%C3%B3n-lounge-pacific-club","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/salones-vip-privados\/sal%C3%B3n-vip-sal%C3%B3n-lounge-pacific-club","Abbreviation":""}}},"LogoMap":{"Translations":{"1":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/104_salon-vip-salon-lounge-pacific-club.png","LocalUrl":"Destinations\/104\/MapLogo_1.png"},"0":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/104_salon-vip-salon-lounge-pacific-club.png","LocalUrl":"Destinations\/104\/MapLogo_0.png"}}},"ExternalDatas":{"Data":[]},"HasAdditionalInfo":false});

