model.Destinations.push( {"Categories":[10],"HiddenTopics":[25],"Topics":[1,5,8,16,19,20],"Id":109,"TextResource":{"Name":"santiago-arrival-shop","Translations":[{"Text":"Santiago Arrival Shop","Abbreviation":""},{"Text":"Santiago Arrival Shop","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"1","Id":207}]},"Description":{"Name":"description","Translations":[{"Text":"<p>¿Quiere comprar los últimos regalos antes de salir del aeropuerto tras su viaje hacia Santiago? Santiago Arrival Shop lo espera con los mejores productos en chocolatería, tabaquería, licores y artículos de belleza justo antes de salir al Hall de recepción.<\/p>\n","Abbreviation":""},{"Text":"<p>Do you want to buy the last gifts before leaving the airport for Santiago? Santiago Arrival Shop looks forward to offering you the best chocolate, tobacco, liquor and beauty products just before the exit to the Reception Hall. <\/p>\n","Abbreviation":""}]},"Created":"1488916788","Updated":"1488916788","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/109_santiago-arrival-shop.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/wines\/santiago-arrival-shop","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/vinos\/santiago-arrival-shop","Abbreviation":""}}},"ExternalDatas":{"Data":[{"key":"field_phone","label":"Phone","field_name":"field_shop_phone"},{"key":"field_shop_site_internet","label":"Website","field_name":"field_shop_site_internet"},{"key":"field_opening_hours","label":"Opening hours","field_name":"field_shop_openinghours"}]},"HasAdditionalInfo":true});

