model.Destinations.push( {"Categories":[8],"HiddenTopics":[],"Topics":[9],"Id":118,"TextResource":{"Name":"tamarugo","Translations":[{"Text":"Tamarugo","Abbreviation":""},{"Text":"Tamarugo","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"3","Id":66},{"FloorId":"1","Id":262}]},"Description":{"Name":"description","Translations":[{"Text":"<p>Bar y cafetería que entrega momentos gratos desde el desayuno hasta la cena. Con una amplia y muy destacada carta de pizzas y sándwiches individuales o para compartir, es muy recomendado si quiere comer algo al paso antes de su vuelo.<\/p>\n","Abbreviation":""},{"Text":"<p>This bar and coffee shop provides pleasant moments from breakfast till dinner. With a wide-ranging and outstanding pizza and sandwich menu, individual or for sharing, it is highly recommended if you want to eat something on the go before your flight<\/p>\n","Abbreviation":""}]},"Created":"1488916788","Updated":"1488916788","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/118_tamarugo.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/restaurants\/tamarugo","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/restaurantes\/tamarugo","Abbreviation":""}}},"LogoMap":{"Translations":{"1":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/118_tamarugo.png","LocalUrl":"Destinations\/118\/MapLogo_1.png"},"0":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/118_tamarugo.png","LocalUrl":"Destinations\/118\/MapLogo_0.png"}}},"ExternalDatas":{"Data":[]},"HasAdditionalInfo":false});

model.Destinations.push( {"Categories":[11],"HiddenTopics":[],"Topics":[7],"Id":119,"TextResource":{"Name":"taxi","Translations":[{"Text":"Taxi Vía","Abbreviation":""},{"Text":"Taxi Vía","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"1","Id":209},{"FloorId":"1","Id":222},{"FloorId":"1","Id":224},{"FloorId":"1","Id":225},{"FloorId":"1","Id":227}]},"Description":{"Name":"description","Translations":[{"Text":"<p>Consiga un transporte seguro y de calidad, conociendo de antemano el valor referencial que tendrá que pagar por cada viaje que realice desde el aeropuerto. Todo gracias al proyecto que busca organizar y coordinar a todos los taxis autorizados que realizan servicios desde el terminal.<\/p>\n","Abbreviation":""},{"Text":"<p>Get safe, quality transportation services and find out beforehand the reference fares for each trip from the airport. This is made possible by a project aimed at organizing and coordinating all authorized taxi services departing from the terminal: Via Controlada.<\/p>\n","Abbreviation":""}]},"Created":"1488916788","Updated":"1488916788","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/119_taxi.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/taxi\/taxi-v%C3%ADa","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/taxi\/taxi-v%C3%ADa","Abbreviation":""}}},"ExternalDatas":{"Data":[]},"HasAdditionalInfo":false});

