model.Destinations.push( {"Categories":[8],"HiddenTopics":[26],"Topics":[10],"Id":131,"TextResource":{"Name":"vinum","Translations":[{"Text":"Vinum","Abbreviation":""},{"Text":"Vinum","Abbreviation":""}]},"ShapeIndexes":{"ActualShapeList":[{"FloorId":"3","Id":133}]},"Description":{"Name":"description","Translations":[{"Text":"<p>Si hablamos de Chile, hablamos de vinos. Y en este bar puede encontrar lo mejor de las distintas cepas y etiquetas nacionales para disfrutar de una experiencia inolvidable antes de dejar el país, junto con espumantes y platos simples que entregan un maridaje perfecto.<\/p>\n","Abbreviation":""},{"Text":"","Abbreviation":""}]},"Created":"1488916796","Updated":"1488916796","Picture":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/131_vinum.png"},"Url":{"Name":"Url","Translations":{"1":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/en\/bar\/vinum","Abbreviation":""},"0":{"Text":"http:\/\/front-airport-pudahuel.viadirect.com\/es\/bar\/vinum","Abbreviation":""}}},"LogoMap":{"Translations":{"1":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/131_vinum.png","LocalUrl":"Destinations\/131\/MapLogo_1.png"},"0":{"Url":"http:\/\/front-airport-pudahuel.viadirect.com\/sites\/default\/files\/viadirect\/logos\/map\/0\/131_vinum.png","LocalUrl":"Destinations\/131\/MapLogo_0.png"}}},"ExternalDatas":{"Data":[]},"HasAdditionalInfo":false});

